module test ();

// === Global Sync Signal ===
reg llm_go_signal = 1;


reg  clk,rst;

wire out1;
wire out2;
wire out3;

freq_div dut(.CLK_in(clk),.RST(rst),.CLK_50(out1),.CLK_10(out2),.CLK_1(out3));

initial begin
	clk = 0;
	forever #5 clk = ~clk;
end

integer error=0;

initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

	#10;
	rst = 1;
	#35;
	rst = 0;
	// 45, clk: 1, clk50: 0, rclk10: 0, clk1: 0
	error = (out1 != 0 || out2 != 0 || out3 !=0 ) ? error+1 : error;
	// 55, clk: 1, clk50: 1, rclk10: 0, clk1: 0
	#10;
	error = (out1 != 1 || out2 != 0 || out3 !=0 ) ? error+1 : error;
	// 95, clk50: 0, rclk10: 1, clk1: 0
	#40;
	error = (out1 != 1 || out2 != 1 || out3 !=0 ) ? error+1 : error;
	// 225, clk: 1, clk50: 0, rclk10: 1, clk1: 0
	#130;
	error = (out1 != 0 || out2 != 1 || out3 !=0 ) ? error+1 : error;
	// 625, clk: 1, clk50: 0, rclk10: 1, clk1: 1
	#400;
	error = (out1 != 0 || out2 != 1 || out3 !=1 ) ? error+1 : error;
	// 1035, clk: 1, clk50: 1, rclk10: 1, clk1: 1
	#410;
	error = (out1 != 1 || out2 != 1 || out3 !=1 ) ? error+1 : error;
	if (error == 0) begin
            $display("===========Your Design Passed===========");
        end
        else begin
        $display("===========Error===========", error);
        end
	$finish;
end

// initial begin 
// 	repeat(500) begin
//
    // wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB
 		// #5
// 		$display("Time: %t, clk: %b, clk50: %b, rclk10: %b, clk1: %b", $time, clk, out1, out2, out3);
// 	end
// end





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "out1,");
      $fwrite(file_mantra, "out2,");
      $fwrite(file_mantra, "out3,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", out1);
        $fwrite(file_mantra, "%h, ", out2);
        $fwrite(file_mantra, "%h, ", out3);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    // Ensure we have control before proceeding (though initially 1, this follows structure)
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    // Initialize inputs
    rst = 1;

    // Wait for global reset stabilization (Clock period is 10ns from original TB)
    #20;

    // ---------------------------------------------------------
    // Test Case 1: Normal Operation & Counter Boundaries
    // ---------------------------------------------------------
    // Release Reset on negedge to avoid race conditions
    @(negedge clk);
    rst = 0;

    // Run for 120 clock cycles to cover:
    // - CLK_50 (toggles every 1 cycle)
    // - CLK_10 (toggles every 5 cycles)
    // - CLK_1 (toggles every 50 cycles)
    // This ensures we hit the max values of cnt_10 (4) and cnt_100 (49)
    // and verify the rollover logic.
    for (i = 0; i < 120; i = i + 1) begin
        @(posedge clk);
    end

    // ---------------------------------------------------------
    // Test Case 2: Asynchronous Reset Sensitivity
    // ---------------------------------------------------------
    // Assert reset at negedge clk. If the design has async reset (posedge RST), 
    // outputs should clear immediately before the next posedge clk.
    // This targets mutations that might remove 'posedge RST' from sensitivity list.
    @(negedge clk);
    rst = 1;
    #2; // Hold for a fraction of the cycle
    rst = 0;

    // ---------------------------------------------------------
    // Test Case 3: Mid-Sequence Reset (Control Flow)
    // ---------------------------------------------------------
    // Allow counters to increment partially (e.g., cnt_10 = 3)
    repeat(3) @(posedge clk);

    // Assert reset to force state to 0 in the middle of a count
    rst = 1;
    #10; // Hold for 1 full cycle
    rst = 0;

    // Verify recovery: cnt_10 should restart from 0.
    // Next CLK_10 toggle should be 5 cycles away.
    // If reset failed (mutation), it would toggle sooner (e.g. in 2 cycles).
    repeat(10) @(posedge clk);

    // ---------------------------------------------------------
    // Test Case 4: Long duration run for CLK_1 stability
    // ---------------------------------------------------------
    // CLK_1 period is 100 cycles. Run for 60 more to see transitions
    // and ensure cnt_100 resets properly after reaching 49.
    for (i = 0; i < 60; i = i + 1) begin
        @(posedge clk);
    end

    // 4. Handover to Original Testbench
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

